bl_info = {    "name": "Baking Textures",    "author": "Andrew Frolov",    "version": (0, 1, 0),    "blender": (4, 0, 0),    "location": "View3D > Sidebar > Baking",    "description": "Инструмент для запекания текстур high-poly → low-poly",    "category": "Object",}import bpyfrom . import propertiesfrom . import operatorsfrom . import panels          # ← добавили# ============================================================# РЕГИСТРАЦИЯ# ============================================================classes = (    properties.BakeSettings,    operators.BAKOT_OT_preflight_report,    operators.BAKOT_OT_settings,    operators.BAKOT_OT_quick,    panels.BAKOT_PT_main_panel,   # ← добавили)def register():    for c in classes:        bpy.utils.register_class(c)    bpy.types.Scene.bake_helper = bpy.props.PointerProperty(type=properties.BakeSettings)def unregister():    if hasattr(bpy.types.Scene, "bake_helper"):        del bpy.types.Scene.bake_helper    for c in reversed(classes):        try:            bpy.utils.unregister_class(c)        except Exception:            passif __name__ == "__main__":    try:        unregister()    except Exception:        pass    register()    bpy.ops.bake_helper.settings('INVOKE_DEFAULT')